<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getMenuRadioItemContext } from './menu-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> { children?: Snippet; keepMounted?: boolean; ref?: HTMLSpanElement | null; } let { children, keepMounted = false, ref = $bindable(null), ...rest }: Props = $props(); const item = getMenuRadioItemContext();</script>
{#if keepMounted || item.checked}<span bind:this={ref} {...rest} hidden={!item.checked} aria-hidden="true" data-checked={item.checked ? '' : undefined}>{@render children?.()}</span>{/if}
